<template><b-modal v-model="show" title="Asesor de producto · Información con IA" size="lg" hide-footer modal-class="product-guide-modal" @hidden="closeGuide">
 <section v-if="product" class="product-guide"><nav ref="guideTabs" class="product-guide-tabs" role="tablist" aria-label="Asesoría del producto"><button ref="clientTab" id="product-client-tab" type="button" role="tab" :aria-selected="activeTab==='clients'?'true':'false'" :tabindex="activeTab==='clients'?0:-1" aria-controls="product-client-panel" :class="{active:activeTab==='clients'}" @click="selectGuideTab('clients')" @keydown.right.prevent="selectGuideTab('expert',true)" @keydown.left.prevent="selectGuideTab('expert',true)"><span aria-hidden="true">◉</span> Asesoría para clientes</button><button ref="expertTab" id="product-expert-tab" type="button" role="tab" :aria-selected="activeTab==='expert'?'true':'false'" :tabindex="activeTab==='expert'?0:-1" aria-controls="product-expert-panel" :class="{active:activeTab==='expert'}" @click="selectGuideTab('expert')" @keydown.left.prevent="selectGuideTab('clients',true)" @keydown.right.prevent="selectGuideTab('clients',true)"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m8 8-4 4 4 4m8-8 4 4-4 4m-3-11-2 22" stroke-linecap="round" stroke-linejoin="round"/></svg> Técnico experto</button></nav><header><span class="product-guide-tag">{{activeTab==='clients'?'ASESORÍA PARA CLIENTES':'TÉCNICO EXPERTO · CONSULTA Y COMPATIBILIDAD'}}</span><h2>{{product.Producto}}</h2><p class="product-model">Modelo: {{draft.model || 'Por identificar'}} <button type="button" title="Corregir modelo y buscar características" aria-label="Corregir modelo y buscar características" @click="correctModel" :disabled="busy" class="product-search-icon"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5" stroke-linecap="round"/></svg></button></p></header><div v-show="activeTab==='clients'" id="product-client-panel" class="product-client-panel" role="tabpanel" aria-labelledby="product-client-tab"><section class="product-guide-catalog"><strong>{{saved?'Características guardadas del producto':'Características del producto'}}</strong><ol v-if="catalogItems.length" class="product-spec-items"><li v-for="(item,i) in catalogItems" :key="i">{{item}}</li></ol><p v-else>Todavía no tiene características guardadas. Busca por nombre del producto, servicio o modelo; revisa y guarda la ficha.</p><span v-if="saved" class="product-guide-saved-badge">Ficha revisada y guardada</span><p v-if="saved && saved.pending" class="product-guide-note">Por confirmar: {{saved.pending}}</p><small v-if="saved">Revisión {{saved.revision}} · {{saved.saved_by}} · {{saved.saved_at}}</small><p v-if="catalogChanged" class="product-guide-note">El catálogo cambió después de esta revisión. Comprueba que la ficha siga correspondiendo al producto.</p></section>
 <producto-imagenes-referencia v-if="show && settings" :product-id="product.IdProducto" :product-name="product.Producto" :model="draft.model" :csrf="settings.csrf" :can-edit="canEdit" :initial-reference="referenceImage" />
 <section class="product-guide-usage"><h3>Usado para · Referencia comercial</h3><p class="product-guide-note">Orientación para asesorar al cliente. Se guarda solo aquí; no forma parte de las características ni de la proforma.</p><ul v-if="draft.used_for"><li v-for="(item,i) in usageItems" :key="i">{{item}}</li></ul><p v-else>Aún no hay referencias guardadas.</p><div class="product-guide-resource-links"><button type="button" :disabled="busy || !canQuery" @click="investigateUsage">Investigar aplicaciones, profesiones y negocios</button><button type="button" @click="usageEditor=!usageEditor" :disabled="busy">Editar referencia</button></div><div v-if="usageEditor"><label>Aplicaciones, profesiones y negocios afines<textarea v-model="draft.used_for" :disabled="busy || !canEdit" rows="5" maxlength="4000" placeholder="Aplicaciones: ...&#10;Profesiones afines: ...&#10;Negocios afines: ...&#10;Límites de uso: ..."></textarea></label><button type="button" :disabled="busy || !canEdit || !draft.used_for.trim()" @click="saveUsage">Guardar referencia de uso</button></div><p v-if="usageSuccess" role="status" class="product-knowledge-success">{{usageSuccess}}</p><small v-if="usageSaved">Referencia guardada por {{usageSaved.saved_by}} · {{usageSaved.saved_at}}</small></section>
 <section class="product-knowledge"><div class="product-guide-answer-head"><strong>Alimentar y guardar características</strong><button type="button" @click="editorOpen=!editorOpen">{{editorOpen?'Ocultar edición':'Editar o completar ficha'}}</button></div><p v-if="saveSuccess" class="product-knowledge-success" role="status">{{saveSuccess}}</p><form v-if="editorOpen" class="product-knowledge-form" @submit.prevent="saveKnowledge"><label>Buscar características por<select v-model="searchBy" :disabled="busy"><option value="name">Nombre del producto o servicio</option><option value="model">Modelo exacto / número de parte</option></select></label><label v-if="searchBy==='name'">Nombre comercial<input v-model="searchName" maxlength="300" :disabled="busy" placeholder="Ej. Sistema de market Neurosoft, ERP, servicio de instalación"></label><label>Modelo exacto / número de parte (opcional al buscar por nombre)<input ref="modelInput" v-model="draft.model" maxlength="200" placeholder="Ej. ADP-65JH, HAC-T1A11N o 15-FD2378LA" :disabled="busy"></label><p class="product-guide-note">Para sistemas y servicios busca por su nombre comercial. Para equipos, el modelo exacto permite confirmar variantes y compatibilidad. Revisa las fuentes antes de guardar.</p><button type="button" :disabled="busy || !canQuery" @click="searchModel" class="product-search-action"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5" stroke-linecap="round"/></svg> {{searchBy==='name'?'Buscar producto y autocompletar':'Buscar modelo y autocompletar'}}</button><label>Características comprobadas<textarea v-model="draft.characteristics" :disabled="busy" rows="4" maxlength="12000" required placeholder="Completa los valores exactos. La búsqueda llena un borrador que debes revisar antes de guardar."></textarea></label><details><summary>Fuentes y datos por confirmar</summary><label>Enlaces de respaldo (uno por línea)<textarea v-model="draft.sourceText" :disabled="busy" rows="2" maxlength="42000" placeholder="https://fabricante.com/ficha-del-modelo"></textarea></label><label>Referencia comprobada<input v-model="draft.reference" :disabled="busy" maxlength="1000" placeholder="Ej. etiqueta del producto, ficha impresa o documento del fabricante"></label><label>Datos pendientes de confirmar<textarea v-model="draft.pending" :disabled="busy" rows="2" maxlength="4000"></textarea></label></details><label class="product-knowledge-reviewed"><input type="checkbox" v-model="reviewed" :disabled="busy"> He comprobado que estas características corresponden a este producto.</label><button type="submit" class="product-knowledge-save" :disabled="busy || !canEdit || !reviewed || !draft.characteristics.trim()">Guardar ficha revisada</button><p v-if="!canEdit" class="product-guide-note">Puedes consultar y preparar información. Los vendedores con permiso para operar el punto de venta pueden guardar fichas compartidas.</p><small>La ficha queda vinculada al producto y conserva un historial de revisiones. Los precios, stock y ventas no se modifican.</small></form></section>
 <div class="product-guide-tools"><button type="button" @click="readAll" :disabled="busy || !readText || !voiceSupported">▶ Leer ficha completa</button><button v-if="reading" type="button" @click="pauseReading">{{paused?'Continuar lectura':'Pausar'}}</button><button v-if="reading" type="button" @click="stopReading">Detener</button><label>Voz del equipo<select v-model="voiceChoice" @change="saveVoice"><option value="">Español automático</option><option v-for="v in voices" :key="v.voiceURI" :value="v.voiceURI">{{v.name}} · {{v.lang}}</option></select></label></div><p v-if="reading" class="product-guide-progress" role="status">{{paused?'Lectura en pausa':'Leyendo'}} · Parte {{readIndex+1}} de {{readCount}}</p><p v-if="voiceError" role="status" class="product-guide-error">{{voiceError}}</p><p v-if="!voiceSupported" class="product-guide-note">Este navegador no dispone de lectura por voz.</p>
 <p v-if="busy" class="product-guide-loading" role="status">Preparando la ficha del modelo y sus fuentes… Puedes cerrar esta ventana en cualquier momento.</p><p v-if="error" class="product-guide-error" role="alert">{{error}}</p><div v-if="settings && (!settings.enabled || !settings.configured)" class="product-guide-note"><p>El superadmin puede activar la conexión de OpenAI en ALI.</p><button v-if="settings.superadmin" type="button" @click="openSettings">Configurar ALI</button></div>
 <section v-if="answer && !answerIsSaved" class="product-guide-answer" ref="technicalAnswer"><div class="product-guide-answer-head"><strong>{{lastQuestion?'Respuesta técnica · '+lastQuestion:'Características del modelo'}}</strong><span>{{answerIsSaved?'Ficha revisada y guardada':(cached?'Borrador IA reciente':'Borrador IA · Revisa antes de guardar')}}</span></div><ol class="product-spec-items"><li v-for="(item,i) in answerItems" :key="i">{{item}}</li></ol><p class="product-guide-note">Comprueba el modelo exacto, accesorios, compatibilidad y garantía antes de ofrecerlos. {{settings && !settings.web?'La búsqueda web está desactivada; esta explicación no tiene verificación externa.':''}}</p><small v-if="createdAt">Consulta: {{consultedDate}} · {{model}}</small></section>
 <section class="product-guide-resources"><h3>Videos de este modelo</h3><a v-for="v in videos" :key="v.url" :href="v.url" target="_blank" rel="noopener noreferrer">▶ {{v.title}}</a><p v-if="answer && !videos.length">No se encontró un video específico citado en esta consulta. Puedes buscar por el nombre y modelo exactos:</p><div class="product-guide-resource-links"><a :href="videoSearch" target="_blank" rel="noopener noreferrer">Buscar videos del modelo en YouTube</a><a :href="specSearch" target="_blank" rel="noopener noreferrer">Buscar ficha del fabricante</a></div><details v-if="sources.length"><summary>Fuentes consultadas ({{sources.length}})</summary><ol><li v-for="s in sources" :key="s.url"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title || s.url}}</a></li></ol></details></section>
 </div><div v-show="activeTab==='expert'" id="product-expert-panel" role="tabpanel" aria-labelledby="product-expert-tab"><p class="product-guide-note">Consulta uso, compatibilidad o compara dispositivos con su nombre y modelo. La respuesta se muestra debajo del formulario.</p><p v-if="settings && !canQuery" class="product-guide-note">Activa la conexión de OpenAI en ALI para realizar consultas técnicas.</p><form class="product-guide-question product-technical-search" @submit.prevent="consultTechnical"><h3>Consulta técnica y comparativa</h3><section class="product-query-device"><div class="product-guide-answer-head"><strong>Equipo o accesorio que deseas consultar</strong><button type="button" @click="useSelectedDevice" :disabled="busy">Usar producto seleccionado</button></div><label>Nombre del equipo / accesorio<input v-model="consultDeviceName" maxlength="300" required placeholder="Ej. laptop HP, memoria RAM o cámara"></label><label>Modelo del equipo / accesorio<input v-model="consultDeviceModel" maxlength="200" placeholder="Se completa desde el producto; puedes corregirlo para esta consulta"></label><small>Estos datos se usan solo en la consulta. No cambian el producto ni su ficha.</small></section><div class="product-technical-options"><label>Tipo de consulta<select v-model="consultationType"><option value="uso">Uso del producto</option><option value="compatibilidad">Compatibilidad</option><option value="comparativa">Comparar dispositivos</option></select></label><label>Otro dispositivo / modelo / nombre<input v-model="comparisonModel" maxlength="200" :required="consultationType!=='uso'" placeholder="Marca y modelo exactos del otro dispositivo"></label></div><label>Pregunta técnica<textarea v-model="question" maxlength="1100" rows="2" :required="!comparisonModel.trim()" placeholder="Ej. ¿Puedo conectar esta cámara a mi grabador? ¿Qué diferencias tiene con el otro modelo?"></textarea></label><div><button type="submit" class="product-search-action" :disabled="busy || !canQuery"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5" stroke-linecap="round"/></svg> Consultar con IA</button><button v-if="answer" type="button" :disabled="busy" @click="searchModel">Actualizar ficha</button></div><small>La consulta usa el producto seleccionado y el modelo indicado. La respuesta técnica no reemplaza la ficha guardada.</small><section ref="technicalFeedback" class="product-technical-feedback" aria-live="polite" aria-atomic="false"><p v-if="technicalPending" class="product-guide-loading" role="status">Consultando el modelo y sus fuentes… La respuesta aparecerá aquí.</p><p v-if="technicalError" class="product-guide-error" role="alert">{{technicalError}}</p><article v-if="technicalResult && !technicalPending" class="product-technical-result"><h3>Respuesta a tu consulta</h3><p class="product-technical-question">{{technicalQuestion}}</p><ol class="product-spec-items"><li v-for="(item,i) in technicalItems" :key="i">{{item}}</li></ol><p v-if="!technicalItems.length" class="product-guide-note">No se recibió una respuesta con contenido. Vuelve a consultar.</p><details v-if="technicalResult.sources.length"><summary>Fuentes de esta respuesta ({{technicalResult.sources.length}})</summary><ul><li v-for="source in technicalResult.sources" :key="source.url"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title || source.url}}</a></li></ul></details></article></section></form></div>
 <div class="product-guide-footer"><button type="button" @click="show=false;closeGuide()">Cerrar</button></div>
 </section>
</b-modal></template>
<script>
import ProductoImagenesReferencia from './ProductoImagenesReferencia.vue';
import {guideUrl,guideFragments,guideChunks,guideVideos,guideItems} from '@/utils/productGuide';
export default {components:{ProductoImagenesReferencia},data(){return {show:false,activeTab:'clients',referenceImage:'',searchBy:'model',searchName:'',product:null,settings:null,question:'',comparisonModel:'',consultDeviceName:'',consultDeviceModel:'',consultationType:'uso',lastQuestion:'',technicalPending:false,technicalResult:null,technicalError:'',technicalQuestion:'',answer:'',sources:[],citations:[],cached:false,createdAt:'',model:'',busy:false,error:'',voiceError:'',saved:null,usageSaved:null,usageEditor:false,usageSuccess:'',usageOnly:false,canEdit:false,editorOpen:true,catalogChanged:false,reviewed:false,saveSuccess:'',answerIsSaved:false,draft:{model:'',characteristics:'',used_for:'',pending:'',sourceText:'',reference:''},voices:[],voiceChoice:'',voiceSupported:!!window.speechSynthesis,reading:false,paused:false,readIndex:0,readCount:0}},computed:{technicalItems(){return this.technicalResult?guideItems(guideFragments(this.technicalResult.text,this.technicalResult.citations||[]).map(f=>f.text).join('')):[]},usageItems(){return guideItems(this.draft.used_for)},catalogItems(){return guideItems(this.saved?this.saved.characteristics:(this.product.ProductoDesc||this.product.ProductoDescCorto||''))},answerItems(){return guideItems(this.fragments.filter(f=>!f.url).map(f=>f.text).join('')).filter(s=>!/^Usado para:/i.test(s))},canQuery(){return this.settings&&this.settings.enabled&&this.settings.configured},fragments(){return guideFragments(this.answer,this.citations)},videos(){return guideVideos(this.sources)},videoSearch(){return 'https://www.youtube.com/results?search_query='+encodeURIComponent([this.product.Producto,this.draft.model,'demostración tutorial'].filter(Boolean).join(' '))},specSearch(){return 'https://www.google.com/search?q='+encodeURIComponent([this.product.Producto,this.draft.model,'fabricante ficha técnica'].filter(Boolean).join(' '))},readText(){if(!this.product)return '';return [this.product.Producto,this.draft.model?'Modelo '+this.draft.model:'',this.product.ProductoDesc||this.product.ProductoDescCorto||'',this.draft.characteristics||this.answer,this.draft.used_for?'Usado para: '+this.draft.used_for:'',this.technicalResult?this.technicalResult.text:'',this.lastQuestion?this.answer:'',this.draft.pending?'Por confirmar: '+this.draft.pending:''].filter(Boolean).join('. ')},consultedDate(){return new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(this.createdAt))}},mounted(){this._cache=new Map();this._version=0;this.$root.$on('ali:product-info',this.openProduct);this.loadVoices();this._voices=()=>this.loadVoices();if(window.speechSynthesis)window.speechSynthesis.addEventListener('voiceschanged',this._voices)},beforeDestroy(){this.$root.$off('ali:product-info',this.openProduct);if(window.speechSynthesis)window.speechSynthesis.removeEventListener('voiceschanged',this._voices);this.closeGuide()},methods:{selectGuideTab(tab,focus=false){this.stopReading();this.activeTab=tab;this.$nextTick(()=>{if(focus)this.$refs[tab==='expert'?'expertTab':'clientTab'].focus();if(this.$refs.guideTabs)this.$refs.guideTabs.scrollIntoView({block:'start'})})},useSelectedDevice(){this.consultDeviceName=this.product?this.product.Producto:'';this.consultDeviceModel=this.draft.model||''},async investigateUsage(){if(this.busy)return;const original=this.question;this.usageOnly=true;this.question='REFERENCIA_USOS: Investiga aplicaciones concretas, profesiones afines, negocios afines y limites de uso de este modelo exacto.';try{await this.query(true)}finally{this.question=original;this.usageOnly=false}},async saveUsage(){if(this.busy||!this.canEdit)return;this.busy=true;this.error='';this.usageSuccess='';const version=this._version;try{const data=await this.request('producto',{mode:'usage_save',id:this.product.IdProducto,used_for:this.draft.used_for,revision:this.usageSaved?this.usageSaved.revision:0});if(version!==this._version||!this.show)return;this.usageSaved=data.usage;this.usageEditor=false;this.usageSuccess='Referencia guardada. Disponible en esta ventana para próximas consultas.'}catch(e){if(version===this._version)this.error=e.message}finally{if(version===this._version)this.busy=false}},async consultTechnical(){if(this.busy||!this.canQuery)return;const detail=this.question.trim();const target=this.comparisonModel.trim();const prompt=[this.consultationType==='comparativa'?'Compara este producto con':this.consultationType==='compatibilidad'?'Verifica la compatibilidad de este producto con':'Consulta de uso de este producto',target,detail].filter(Boolean).join('. ');this.technicalQuestion=detail||target;this.technicalResult=null;this.technicalError='';this.technicalPending=true;const pending=this.query(true,prompt);const version=this._version;this.$nextTick(()=>this.activeTab==='expert'&&this.$refs.technicalFeedback&&this.$refs.technicalFeedback.scrollIntoView({behavior:'smooth',block:'nearest'}));await pending;if(version!==this._version||!this.show)return;this.technicalPending=false;this.technicalError=this.error;this.$nextTick(()=>this.activeTab==='expert'&&this.$refs.technicalFeedback&&this.$refs.technicalFeedback.scrollIntoView({behavior:'smooth',block:'nearest'}))},correctModel(){this.activeTab='clients';this.editorOpen=true;this.$nextTick(()=>{this.$refs.modelInput.focus();this.$refs.modelInput.select()})},searchModel(){this.activeTab='clients';this.question='';this.query(true)},
 async request(path,body,signal){const r=await fetch('/api/index.php/ali/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.settings?this.settings.csrf:''},body:body?JSON.stringify(body):undefined,signal});let data;try{data=await r.json()}catch(e){throw Error('La respuesta del servidor no es válida. Revisa la conexión.')}if(!r.ok)throw Error(data.error||'No se pudo completar la consulta.');return data},
 async openProduct(item){if(!item||!Number(item.IdProducto))return;this.closeGuide();this.activeTab='clients';this.referenceImage=item.referenceImage||'';this.searchBy='model';this.searchName=item.Producto||'';this.product={IdProducto:item.IdProducto,Producto:item.Producto||'Producto',ProductoModelo:item.ProductoModelo||'',ProductoDesc:item.ProductoDesc||item.descripcion_detallada||'',ProductoDescCorto:item.ProductoDescCorto||item.descripcion||''};this.question='';this.comparisonModel='';this.consultDeviceName=this.product.Producto;this.consultDeviceModel='';this.lastQuestion='';this.technicalResult=null;this.technicalPending=false;this.technicalError='';this.technicalQuestion='';this.answer='';this.sources=[];this.citations=[];this.error='';this.createdAt='';this.settings=null;this.saved=null;this.usageSaved=null;this.usageEditor=false;this.usageSuccess='';this.usageOnly=false;this.canEdit=false;this.editorOpen=true;this.catalogChanged=false;this.reviewed=false;this.saveSuccess='';this.answerIsSaved=false;this.draft={model:'',characteristics:'',used_for:'',pending:'',sourceText:'',reference:''};this.show=true;this.busy=true;const version=++this._version;this._abort=new AbortController();this._deadline=setTimeout(()=>this._abort&&this._abort.abort(),15000);try{const settings=await this.request('config',null,this._abort.signal);if(version!==this._version||!this.show)return;this.settings=settings;const metadata=await this.request('producto',{mode:'knowledge_get',id:this.product.IdProducto},this._abort.signal);if(version!==this._version||!this.show)return;this.canEdit=!!metadata.can_edit;this.catalogChanged=!!metadata.catalog_changed;if(metadata.product){this.product=Object.assign({},this.product,metadata.product);this.draft.model=metadata.suggested_model||'';}if(metadata.knowledge)this.applyKnowledge(metadata.knowledge);this.searchName=this.product.Producto;this.searchBy=/[0-9]/.test(this.draft.model)?'model':'name';this.useSelectedDevice();this.usageSaved=metadata.usage||null;this.draft.used_for=metadata.usage?metadata.usage.used_for:((metadata.knowledge||{}).used_for||'');try{this.voiceChoice=localStorage.getItem('product-guide:voice:'+settings.user)||''}catch(e){}this.busy=false;clearTimeout(this._deadline);if(this.canQuery&&!this.saved)await this.query(false)}catch(e){if(version!==this._version)return;this.error=e.name==='AbortError'?'La conexión tardó demasiado. Puedes volver a intentar.':e.message;this.busy=false}finally{if(version===this._version)clearTimeout(this._deadline)}},
 async query(refresh=false,explicitQuestion=null){if(!this.product||this.busy||!this.canQuery)return;this.stopReading();const queryQuestion=explicitQuestion===null?this.question:explicitQuestion;const key=JSON.stringify([this.product,this.searchBy,this.searchName,this.draft.model,queryQuestion,this.settings.model,this.settings.web,this.technicalPending?[this.consultDeviceName,this.consultDeviceModel]:null]);if(!refresh&&this._cache.has(key)){this.applyAnswer(Object.assign({},this._cache.get(key),{cached:true}));return;}const version=++this._version;if(this._abort)this._abort.abort();this._abort=new AbortController();clearTimeout(this._deadline);this._deadline=setTimeout(()=>this._abort&&this._abort.abort(),65000);this.busy=true;this.error='';this.reviewed=false;this.saveSuccess='';try{const data=await this.request('producto',{mode:'sales',id:this.product.IdProducto,question:queryQuestion,refresh:!!refresh,exact_model:this.draft.model,search_by:this.technicalPending?'model':this.searchBy,search_name:this.searchName,...(this.technicalPending?{technical_context:{name:this.consultDeviceName.trim(),model:this.consultDeviceModel.trim()}}:{})},this._abort.signal);if(version!==this._version||!this.show)return;this._cache.set(key,data);if(this._cache.size>30)this._cache.delete(this._cache.keys().next().value);this.applyAnswer(data)}catch(e){if(version===this._version)this.error=e.name==='AbortError'?'La consulta tardó demasiado. Puedes volver a intentar.':e.message}finally{if(version===this._version){this.busy=false;clearTimeout(this._deadline)}}},
 applyAnswer(data){if(this.technicalPending){this.technicalResult={text:data.text||'',citations:data.citations||[],sources:(data.sources||[]).filter(s=>guideUrl(s.url))};return;}if(this.usageOnly){if(data.needs_model){this.error='Completa el modelo exacto antes de investigar usos.';this.editorOpen=true;return;}this.draft.used_for=guideFragments(data.text||'',data.citations||[]).filter(f=>!f.url).map(f=>f.text).join('').trim();this.usageEditor=true;this.usageSuccess='Borrador orientativo. Revisa los usos antes de guardar la referencia.';return;}this.lastQuestion=this.question.trim();this.answerIsSaved=false;this.answer=data.text||'';this.sources=(data.sources||[]).map(s=>({url:guideUrl(s.url),title:s.title})).filter(s=>s.url);this.citations=data.citations||[];this.cached=!!data.cached;this.createdAt=data.created_at||'';this.model=data.model||'';if(data.exact_model)this.draft.model=data.exact_model;if(!data.needs_model&&!this.question.trim()){this.draft.characteristics=guideFragments(this.answer,this.citations).filter(f=>!f.url).map(f=>f.text).join('').trim();this.draft.characteristics=guideItems(this.draft.characteristics).filter(s=>!/^Usado para:/i.test(s)).map((s,i)=>(i+1)+'. '+s).join('\n');const usage=guideItems(guideFragments(this.answer,this.citations).filter(f=>!f.url).map(f=>f.text).join('')).find(s=>/^Usado para:/i.test(s));if(usage)this.draft.used_for=usage.replace(/^Usado para:\s*/i,'');this.draft.sourceText=this.sources.slice(0,20).map(s=>s.url).join('\n');this.editorOpen=true;}if(data.needs_model){this.editorOpen=true;this.error='Falta el modelo exacto. Completa el número de parte antes de autocompletar.';}},applyKnowledge(row){this.lastQuestion='';this.saved=row;this.draft={model:row.model||'',characteristics:row.characteristics||'',used_for:this.draft.used_for||row.used_for||'',pending:row.pending||'',sourceText:(row.sources||[]).map(s=>s.url).join('\n'),reference:row.reference||''};this.answer=row.characteristics||'';this.sources=(row.sources||[]).filter(s=>guideUrl(s.url));this.citations=[];this.answerIsSaved=true;this.cached=false;this.createdAt=row.saved_at?row.saved_at.replace(' ','T')+'-05:00':'';this.model='Ficha revisada';this.editorOpen=false;},async saveKnowledge(){if(this.busy||!this.canEdit||!this.reviewed)return;this.stopReading();this.busy=true;this.error='';const version=++this._version;this._abort=new AbortController();this._deadline=setTimeout(()=>this._abort&&this._abort.abort(),20000);try{const urls=this.draft.sourceText.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(urls.some(url=>!guideUrl(url)))throw Error('Revisa los enlaces de respaldo: deben comenzar con http o https.');const data=await this.request('producto',{mode:'knowledge_save',id:this.product.IdProducto,model:this.draft.model,characteristics:this.draft.characteristics,pending:this.draft.pending,reference:this.draft.reference,sources:urls.map(url=>({url,title:((this.sources.find(s=>s.url===url)||{}).title||url).slice(0,300)})),revision:this.saved?this.saved.revision:0,reviewed:true},this._abort.signal);if(version!==this._version||!this.show)return;this.applyKnowledge(data.knowledge);this.catalogChanged=false;this.reviewed=false;this._cache.clear();this.saveSuccess='Ficha guardada. Se mostrará en las próximas consultas de este producto.';}catch(e){if(version===this._version)this.error=e.name==='AbortError'?'No se recibió confirmación. Vuelve a abrir la ficha antes de intentar guardar de nuevo.':e.message;}finally{if(version===this._version){this.busy=false;clearTimeout(this._deadline)}}},closeGuide(){this._version=(this._version||0)+1;clearTimeout(this._deadline);if(this._abort)this._abort.abort();this._abort=null;this.busy=false;this.technicalPending=false;this.stopReading()},openSettings(){this.show=false;this.closeGuide();this.$root.$emit('ali:open')},
 loadVoices(){this.voices=window.speechSynthesis?window.speechSynthesis.getVoices().slice().sort((a,b)=>Number(/^es/i.test(b.lang))-Number(/^es/i.test(a.lang))||a.name.localeCompare(b.name)):[]},saveVoice(){this.stopReading();if(this.settings)try{localStorage.setItem('product-guide:voice:'+this.settings.user,this.voiceChoice)}catch(e){}},
 readAll(){if(!this.voiceSupported||!this.readText||this.busy)return;this.stopReading();this.voiceError='';this._chunks=guideChunks(this.readText);this.readIndex=0;this.readCount=this._chunks.length;if(!this.readCount)return;this.reading=true;this.paused=false;this.$root.$emit('diario:dictation',true);this.$root.$emit('ali:product-reading',true);this._readVersion=(this._readVersion||0)+1;this.readChunk(this._readVersion)},readChunk(version){if(!this.reading||version!==this._readVersion)return;if(this.readIndex>=this._chunks.length){this.stopReading();return;}const u=new SpeechSynthesisUtterance(this._chunks[this.readIndex]);const voice=this.voices.find(v=>v.voiceURI===this.voiceChoice)||this.voices.find(v=>/^es[-_]PE/i.test(v.lang))||this.voices.find(v=>/^es/i.test(v.lang));if(voice){u.voice=voice;u.lang=voice.lang}else u.lang='es-PE';u.rate=1;u.onend=()=>{if(version!==this._readVersion)return;clearTimeout(this._speechDeadline);this.readIndex++;this.readChunk(version)};u.onerror=e=>{if(version!==this._readVersion)return;this.stopReading();if(e.error!=='canceled'&&e.error!=='interrupted')this.voiceError='No se pudo continuar la lectura. Selecciona otra voz o vuelve a intentar.'};this._utterance=u;this._speechDeadline=setTimeout(()=>{this.stopReading();this.voiceError='La voz no respondió. Selecciona otra voz y vuelve a intentar.'},45000);window.speechSynthesis.speak(u)},pauseReading(){if(!this.reading)return;if(this.paused){window.speechSynthesis.resume();this.paused=false;this._speechDeadline=setTimeout(()=>this.stopReading(),45000)}else{window.speechSynthesis.pause();this.paused=true;clearTimeout(this._speechDeadline)}},stopReading(){const wasReading=this.reading;this._readVersion=(this._readVersion||0)+1;clearTimeout(this._speechDeadline);if(this._utterance&&window.speechSynthesis)window.speechSynthesis.cancel();this._utterance=null;this.reading=false;this.paused=false;if(wasReading){this.$root.$emit('diario:dictation',false);this.$root.$emit('ali:product-reading',false)}}
}};
